import jakarta.persistence.*;

@Entity                       // 이 클래스는 테이블과 매핑된다
public class Member {

    @Id                       // 이 필드가 기본 키
    private String memberId;

    @Column(name = "NAME")    // 필드 이름과 컬럼 이름이 다르면 적어 준다
    private String username;

    private String tel;       // 이름이 같으면 생략 가능

    protected Member() {}     // JPA 가 리플렉션으로 쓰는 기본 생성자 (5.1절)
}

